async function ingest(req,res){
  const auth=req.headers.authorization||'',m=auth.match(/^Bearer\s+(rc_live_[a-f0-9]{48})$/);if(!m)return reply(res,401,{error:'Missing or invalid API key.'});const key=await pool.query('SELECT k.id,k.tenant_id,k.app_id,a.name FROM api_keys k JOIN apps a ON a.id=k.app_id WHERE k.key_hash=$1 AND k.revoked_at IS NULL AND a.deleted_at IS NULL',[sha(m[1])]);if(!key.rowCount)return reply(res,401,{error:'Missing or invalid API key.'});
  const b=await body(req),events=Array.isArray(b.logs)?b.logs:Array.isArray(b)?b:(b.message||b.log||b.msg)?[b]:[];if(!events.length||events.length>100)return reply(res,400,{error:'Send between 1 and 100 log events per batch.'});const cleanEvents=[];
  for(const e of events){const inputLevel=String(e?.level??e?.severity??'').trim().toLowerCase(),level=({error:'ERROR',warning:'WARN',warn:'WARN',info:'INFO'})[inputLevel],rawMessage=e?.message??e?.log??e?.msg;if(!level||!String(rawMessage||'').trim())return reply(res,400,{error:'Each log needs a message and a level of error, warning or info.'});let message=redact(rawMessage,4000).trim();if(e.stack)message+=`\n${redact(e.stack,1000)}`;let at=Date.parse(e.timestamp??e.time);if(!Number.isFinite(at)||Math.abs(Date.now()-at)>24*60*60*1000)at=Date.now();const duration=Number(e.durationMs??e.duration_ms),status=Number(e.statusCode??e.status_code);cleanEvents.push({at:new Date(at),level,service:redact(e.service??e.service_name??e.container_name??key.rows[0].name,100),message:message.slice(0,5000),duration:Number.isFinite(duration)?Math.max(0,Math.min(3600000,Math.floor(duration))):null,status:Number.isInteger(status)&&status>=100&&status<=599?status:null})}
  if(!cleanEvents.length)return reply(res,400,{error:'No usable log events in the batch.'});const app=key.rows[0];const created=[];const explanations=new Map();for(const e of cleanEvents){if(['ERROR','FATAL'].includes(e.level)){const sig=signature(e.message);if(!explanations.has(sig))explanations.set(sig,await explain(e.message,e.level,pool))}}
  const result=await transaction(async c=>{
    const plan=await c.query('SELECT p.log_limit FROM plans p JOIN tenants t ON t.plan=p.code WHERE t.id=$1',[app.tenant_id]);const cap=plan.rows[0]?.log_limit||1000;const month=new Date(Date.UTC(new Date().getUTCFullYear(),new Date().getUTCMonth(),1));const usage=await c.query(`INSERT INTO usage_counters(tenant_id,month,log_count) VALUES($1,$2,$3) ON CONFLICT(tenant_id,month) DO UPDATE SET log_count=usage_counters.log_count+EXCLUDED.log_count WHERE usage_counters.log_count+EXCLUDED.log_count <= $4 RETURNING log_count`,[app.tenant_id,month,cleanEvents.length,cap]);if(!usage.rowCount)return false;
    for(const e of cleanEvents){await c.query('INSERT INTO logs(tenant_id,app_id,event_at,level,service,message,status_code,duration_ms,template_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)',[app.tenant_id,app.app_id,e.at,e.level,e.service,e.message,e.status,e.duration,signature(e.message).slice(0,32)]);
        if(['ERROR','FATAL'].includes(e.level)){const sig=signature(e.message);await c.query('SELECT pg_advisory_xact_lock(hashtext($1::text),hashtext($2::text))',[app.app_id,sig]);let old=await c.query("SELECT * FROM incidents WHERE app_id=$1 AND signature=$2 AND type='error' AND created_at>now()-interval '30 minutes' ORDER BY created_at DESC LIMIT 1 FOR UPDATE",[app.app_id,sig]);let incident;
        if(old.rowCount){const row=old.rows[0],ev=[...(row.evidence||[]),{timestamp:e.at,level:e.level,service:e.service,message:e.message}].slice(-20);await c.query('UPDATE incidents SET evidence=$1 WHERE id=$2',[JSON.stringify(ev),row.id]);incident={...row,evidence:ev,appName:app.name}}
        else{const explanation=explanations.get(sig),id=uuid(),evidence=[{timestamp:e.at,level:e.level,service:e.service,message:e.message}];const r=await c.query(`INSERT INTO incidents(id,tenant_id,app_id,type,pattern_code,signature,severity,status,title,cause,steps,confidence,evidence)
          VALUES($1,$2,$3,'error','log_error',$4,$5,'open',$6,$7,$8,$9,$10) RETURNING *`,[id,app.tenant_id,app.app_id,sig,e.level==='FATAL'?'critical':'high',explanation.title,explanation.cause,JSON.stringify(explanation.steps),explanation.confidence,JSON.stringify(evidence)]);incident={...r.rows[0],evidence,appName:app.name};created.push(incident)}
        await c.query(`INSERT INTO warning_outcomes(incident_id,followed_by_real_error,lead_time_minutes,judged_at)
          SELECT i.id,true,GREATEST(0,floor(extract(epoch FROM (now()-i.created_at))/60)::int),now() FROM incidents i
          WHERE i.app_id=$1 AND i.type='warning' AND i.created_at<now() AND i.created_at>=now()-interval '60 minutes'
          ON CONFLICT(incident_id) DO UPDATE SET followed_by_real_error=true,lead_time_minutes=EXCLUDED.lead_time_minutes,judged_at=EXCLUDED.judged_at`,[app.app_id]);
      }
    }
    await c.query('UPDATE apps SET last_seen=now() WHERE id=$1',[app.app_id]);await c.query(`INSERT INTO usage_counters(tenant_id,month,log_count) VALUES($1,$2,0) ON CONFLICT DO NOTHING`,[app.tenant_id,month]);return true;
  });
  if(!result)return reply(res,429,{error:'Monthly log limit reached for this plan.'});for(const incident of created)void sendIncident(incident);return reply(res,202,{accepted:cleanEvents.length,app:app.name,incidents:created.length});
}

async function razorpayWebhook(req,res){
  const secret=process.env.RAZORPAY_WEBHOOK_SECRET;if(!secret)return reply(res,503,{error:'Webhook secret is not configured.'});const raw=await readRaw(req),given=req.headers['x-razorpay-signature']||'',eventId=req.headers['x-razorpay-event-id']||'';const expected=crypto.createHmac('sha256',secret).update(raw).digest('hex');if(!given||!equal(given,expected)||!eventId)return reply(res,400,{error:'Invalid webhook signature or event ID.'});let event;try{event=JSON.parse(raw.toString('utf8'))}catch{return reply(res,400,{error:'Invalid webhook JSON.'})};const subscription=event.payload?.subscription?.entity;if(!subscription?.id)return reply(res,200,{ok:true,ignored:true});
  await transaction(async c=>{const minimal=JSON.stringify({subscriptionId:subscription.id,status:subscription.status||null,currentEnd:subscription.current_end||null});const inserted=await c.query('INSERT INTO payment_events(razorpay_event_id,event_type,payload) VALUES($1,$2,$3) ON CONFLICT DO NOTHING RETURNING razorpay_event_id',[eventId,event.event||'unknown',minimal]);if(!inserted.rowCount)return;const row=await c.query('SELECT tenant_id,plan_code FROM subscriptions WHERE razorpay_subscription_id=$1 FOR UPDATE',[subscription.id]);if(!row.rowCount)return;const active=['subscription.activated','subscription.charged','subscription.resumed'].includes(event.event),final=['subscription.cancelled','subscription.completed','subscription.halted','subscription.paused'].includes(event.event),status=event.event==='subscription.authenticated'?'authenticated':active?'active':final?(subscription.status||'cancelled'):['subscription.pending'].includes(event.event)?'pending':(subscription.status||'created'),end=subscription.current_end?new Date(subscription.current_end*1000):null;await c.query('UPDATE subscriptions SET status=$1,current_period_end=$2,cancel_at_cycle_end=CASE WHEN $3 THEN false ELSE cancel_at_cycle_end END,updated_at=now() WHERE tenant_id=$4',[status,end,final,row.rows[0].tenant_id]);if(active)await c.query('UPDATE tenants SET plan=$1 WHERE id=$2',[row.rows[0].plan_code,row.rows[0].tenant_id]);if(final)await c.query("UPDATE tenants SET plan='starter' WHERE id=$1",[row.rows[0].tenant_id])});return reply(res,200,{ok:true});
}

async function serve(req,res){
  const url=new URL(req.url,`http://${req.headers.host||'localhost'}`),p=url.pathname,m=req.method;
  if(m==='GET'&&p==='/health'){try{await pool.query('SELECT 1');return reply(res,200,{status:'ok',database:'connected'})}catch{return reply(res,503,{status:'unavailable'})}}
  if(rateLimited(req,(p==='/v1/logs'||p==='/ingest')?60:(p==='/api/password/forgot'?4:(p==='/api/login'||p==='/api/register'||p==='/api/password/reset'?12:120))))return reply(res,429,{error:'Too many requests. Try again shortly.'});
  if(m==='POST'&&(p==='/api/razorpay/webhook'||p==='/webhooks/razorpay'))return razorpayWebhook(req,res);
  if(m==='POST'&&(p==='/v1/logs'||p==='/ingest'))return ingest(req,res);
  if(m==='GET'&&p.startsWith('/api/')&&String(req.headers.accept||'').includes('text/html')&&!await authenticated(req))return redirectToLogin(res);
  if(p.startsWith('/api/'))return account(req,res,m,p);
  if(m==='GET'&&(p==='/'||p==='/login'||p.endsWith('.html')||p.endsWith('.css')||p.endsWith('.js'))){const file=p==='/'||p==='/login'?'index.html':path.basename(p),full=path.join(ROOT,file);if(!['index.html','homepage.css','earth-root.js','site-theme.css','button-effects.js','starfield.js','dashboard.html','reset-password.html','styles.css','dashboard.css','dashboard-page.css','app.js','dashboard-app.js','razorpay-checkout-client.js','reset-password.js','integrations.html','privacy.html','terms.html'].includes(file)||!fs.existsSync(full))return reply(res,404,{error:'Not found.'});if(file==='dashboard.html'&&!await authenticated(req))return redirectToLogin(res);if(p==='/login'&&await authenticated(req)){res.writeHead(302,{'location':'/dashboard.html','cache-control':'no-store'});res.end();return}const types={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript; charset=utf-8'};const h={'content-type':types[path.extname(full)],'x-content-type-options':'nosniff','x-frame-options':'DENY','referrer-policy':'strict-origin-when-cross-origin','permissions-policy':'camera=(), microphone=(), geolocation=()','content-security-policy':"default-src 'self'; script-src 'self' https://checkout.razorpay.com; style-src 'self' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: https://unpkg.com; connect-src 'self' https://api.razorpay.com; frame-src 'self' https://api.razorpay.com https://checkout.razorpay.com; base-uri 'none'; frame-ancestors 'none'; form-action 'self'",'cache-control':['index.html','homepage.css','earth-root.js','site-theme.css','button-effects.js','starfield.js','dashboard.html','reset-password.html','dashboard-page.css','dashboard-app.js','razorpay-checkout-client.js','app.js'].includes(file)?'no-cache':'public, max-age=3600'};if(req.socket.encrypted||COOKIE_SECURE)h['strict-transport-security']='max-age=31536000; includeSubDomains';res.writeHead(200,h);return fs.createReadStream(full).pipe(res)}
  return reply(res,404,{error:'Not found.'});
}

async function main(){await initialize();const server=http.createServer((req,res)=>{serve(req,res).catch(error=>{console.error('Request failed:',error.message);if(!res.headersSent)reply(res,error.status||500,{error:error.status?error.message:'Something went wrong. Please try again.'})})});server.listen(PORT,HOST,()=>console.log(`RootCause listening on http://${HOST}:${PORT}`));const analyzer=setInterval(()=>runAnalyzer(pool).catch(e=>console.error('Analyzer cycle failed:',e.message)),60_000);analyzer.unref();runAnalyzer(pool).catch(e=>console.error('Initial analysis failed:',e.message));let stopping=false;const shutdown=()=>{if(stopping)return;stopping=true;clearInterval(analyzer);server.close(()=>pool.end().finally(()=>process.exit(0)));setTimeout(()=>pool.end().finally(()=>process.exit(1)),10_000).unref()};process.once('SIGTERM',shutdown);process.once('SIGINT',shutdown)}
main().catch(error=>{console.error(error.message);process.exitCode=1});
